const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const nick=(value='')=>`<label for="auth-nickname">Nickname</label><input id="auth-nickname" name="nickname" value="${esc(value)}" required minlength="3" maxlength="24" pattern="[A-Za-z0-9][A-Za-z0-9_.\\-]{2,23}" autocomplete="username" autocapitalize="none" spellcheck="false" aria-describedby="nickname-help nickname-status"><small id="nickname-help">3–24 znaků, bez diakritiky. Písmena, číslice, tečka, pomlčka nebo podtržítko.</small><p id="nickname-status" class="small" role="status"></p>`;
const password=(fresh=false)=>`<label for="auth-password">${fresh?'Nové heslo':'Heslo'}</label><input id="auth-password" name="password" type="password" required ${fresh?'minlength="15" ':''}autocomplete="${fresh?'new-password':'current-password'}" ${fresh?'aria-describedby="password-help"':''}>${fresh?'<small id="password-help">15–128 znaků. Zkus delší vlastní větu; mezery jsou v pořádku.</small><label for="auth-repeat">Heslo ještě jednou</label><input id="auth-repeat" name="repeat" type="password" required autocomplete="new-password">':''}`;
const remember=checked=>`<label class="check-row"><input name="remember" type="checkbox" ${checked?'checked':''}> Zůstat přihlášený/á 30 dní na tomto zařízení</label><p class="fine-print">Na sdíleném zařízení nech vypnuté. Bez této volby přihlášení platí nejvýše 12 hodin.</p>`;
export function pendingSaveView(pending){return pending?`<aside class="wrap pending-save"><strong>Připraveno k uložení: ${pending.scope==='intimacy'?'intimní profil':'osobnost a temperament'}</strong><p>Po přihlášení se uloží tento dokončený test na tvůj účet. Výsledky budou kdykoliv dostupné z účtu, i na jiném zařízení. Pak můžeš vytvořit kód pro párové porovnávání.</p><button class="text-button" data-p="cancel-save">Zrušit uložení na účet</button></aside>`:'';}
export function signInView(state){const fresh=state.authMode==='register';return `<section class="wrap auth-card paper"><div class="auth-switch" role="group" aria-label="Přístup k účtu"><button class="button ${fresh?'secondary':''}" data-p="auth-mode" data-mode="login" aria-pressed="${!fresh}">Přihlásit se</button><button class="button ${fresh?'':'secondary'}" data-p="auth-mode" data-mode="register" aria-pressed="${fresh}">Vytvořit účet</button></div><h2>${fresh?'Tvůj nový účet.':'Vítej zpátky.'}</h2><form data-form="${fresh?'register':'login'}">${nick(state.authNickname)}${password(fresh)}${remember(state.authRemember)}${fresh?'<p class="auth-warning">Obnovu zapomenutého hesla nenabízíme. Ulož si ho do správce hesel. Nickname nemusí být tvoje skutečné jméno.</p>':'<p class="fine-print">Zapomenuté heslo bohužel nelze obnovit.</p>'}<button class="button" type="submit">${fresh?'Vytvořit účet':'Přihlásit se'}${state.pendingSave?' a uložit výsledek':''} →</button></form><details class="legacy-login"><summary>Mám původní ID účtu a klíč</summary><p>Přihlas se jimi a nastav si nickname a heslo. Tvoje výsledky a vydané kódy zůstanou zachované.</p><form data-form="legacy-login"><label for="legacy-id">Původní ID účtu</label><input id="legacy-id" name="id" required maxlength="17" autocomplete="username" autocapitalize="none" spellcheck="false"><label for="legacy-key">Původní soukromý klíč</label><input id="legacy-key" name="key" type="password" required maxlength="43" autocomplete="current-password"><button class="button secondary" type="submit">Přihlásit původní účet →</button></form></details><p class="fine-print">Kód od partnera patří do <a href="#porovnani">porovnání</a>. <a href="#soukromi">Jak chráníme uložené odpovědi →</a></p></section>`;}
export function accountSecurityView(state){return `<section class="wrap auth-card paper account-security"><${state.legacy?'div':'details'} ${state.legacy?'':'class="password-settings"'}>${state.legacy?'<h2>Přejdi na nickname a heslo.</h2><p>Uložené výsledky i porovnávací kódy zůstanou. Původní klíč po změně přestane fungovat.</p>':'<summary>Změnit heslo</summary>'}<form data-form="${state.legacy?'upgrade-account':'change-password'}"><label for="auth-current">${state.legacy?'Původní soukromý klíč':'Aktuální heslo'}</label><input id="auth-current" name="secret" type="password" required autocomplete="current-password">${state.legacy?nick(state.authNickname):''}${password(true)}${remember(false)}<p class="fine-print">Změna odhlásí ostatní přihlášení k účtu. Zapomenuté heslo nelze obnovit.</p><button class="button secondary" type="submit">${state.legacy?'Nastavit nové přihlášení':'Změnit heslo'}</button></form></${state.legacy?'div':'details'}></section>`;}
